40	/**
41	 * This class coordinates reading and writing Container checksum information for all containers.
42	 */
43	public class ContainerChecksumTreeManager {
44	
45	  private static final Logger LOG = LoggerFactory.getLogger(ContainerChecksumTreeManager.class);
46	
47	  // Used to coordinate reads and writes to each container's checksum file.
48	  // Each container ID is mapped to a stripe.
49	  private final Striped<ReadWriteLock> fileLock;
50	  private final ContainerMerkleTreeMetrics metrics;
51	
52	  /**
53	   * Creates one instance that should be used to coordinate all container checksum info within a datanode.
54	   */
55	  public ContainerChecksumTreeManager(DatanodeConfiguration dnConf) {
56	    fileLock = SimpleStriped.readWriteLock(dnConf.getContainerChecksumLockStripes(), true);
57	    // TODO: TO unregister metrics on stop.
58	    metrics = ContainerMerkleTreeMetrics.create();
59	  }
60	
61	  /**
62	   * Writes the specified container merkle tree to the specified container's checksum file.
63	   * The data merkle tree within the file is replaced with the {@code tree} parameter, but all other content of the
64	   * file remains unchanged.
65	   * Concurrent writes to the same file are coordinated internally.
66	   */
67	  public void writeContainerDataTree(KeyValueContainerData data, ContainerMerkleTree tree) throws IOException {
68	    Lock writeLock = getWriteLock(data.getContainerID());
69	    writeLock.lock();
70	    try {
71	      ContainerProtos.ContainerChecksumInfo newChecksumInfo = read(data).toBuilder()
72	          .setContainerMerkleTree(captureLatencyNs(metrics.getCreateMerkleTreeLatencyNS(), tree::toProto))
73	          .build();
74	      write(data, newChecksumInfo);
75	      LOG.debug("Data merkle tree for container {} updated", data.getContainerID());
76	    } finally {
77	      writeLock.unlock();
78	    }
79	  }
80	
81	  /**
82	   * Adds the specified blocks to the list of deleted blocks specified in the container's checksum file.
83	   * All other content of the file remains unchanged.
84	   * Concurrent writes to the same file are coordinated internally.
85	   */
86	  public void markBlocksAsDeleted(KeyValueContainerData data, SortedSet<Long> deletedBlockIDs) throws IOException {
87	    Lock writeLock = getWriteLock(data.getContainerID());
88	    writeLock.lock();
89	    try {
90	      ContainerProtos.ContainerChecksumInfo.Builder checksumInfoBuilder = read(data).toBuilder();
91	      // Although the persisted block list should already be sorted, we will sort it here to make sure.
92	      // This will automatically fix any bugs in the persisted order that may show up.
93	      SortedSet<Long> sortedDeletedBlockIDs = new TreeSet<>(checksumInfoBuilder.getDeletedBlocksList());
94	      // Since the provided list of block IDs is already sorted, this is a linear time addition.
95	      sortedDeletedBlockIDs.addAll(deletedBlockIDs);
96	
97	      checksumInfoBuilder
98	          .clearDeletedBlocks()
99	          .addAllDeletedBlocks(sortedDeletedBlockIDs)
100	          .build();
101	      write(data, checksumInfoBuilder.build());
102	      LOG.debug("Deleted block list for container {} updated", data.getContainerID());
103	    } finally {
104	      writeLock.unlock();
105	    }
106	  }
107	
108	  public ContainerDiff diff(KeyValueContainerData thisContainer, ContainerProtos.ContainerChecksumInfo otherInfo)
109	      throws IOException {
110	    // TODO HDDS-10928 compare the checksum info of the two containers and return a summary.
111	    //  Callers can act on this summary to repair their container replica using the peer's replica.
112	    //  This method will use the read lock, which is unused in the current implementation.
113	    return new ContainerDiff();
114	  }
